import {advisoryValidity} from './advisory-validity.mjs';
import {evidenceKind,evidenceKindLabel,withEvidenceKind} from './evidence-kind.mjs';
import {evidencePanelMarkup,safeEvidenceUrl} from './evidence-panel.mjs';
import {siteUrl,runtime} from './runtime-config.mjs';
import {COVERAGE_NOTES,COVERAGE_REVIEW_DATE} from './intelligence-context.mjs';
import {selectEvidence,priceComparison,oilMechanisms,contextAge,evidenceDate,MECHANISMS} from './situation-data.mjs';
import {REVIEW_DATE,MARKET_CONTEXT,REGIONAL_ACTORS,CONTEXT_SOURCES,INFRASTRUCTURE} from './energy-context.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>value?new Date(value).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}):'Unknown';
const dollars=value=>Number.isFinite(value)?'$'+value.toFixed(2):'No observation';
const link=(url,label)=>`<a href="${esc(url.startsWith('/')?siteUrl(url):url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
const reviewedContext=COVERAGE_NOTES.map(r=>({...withEvidenceKind(r),recordType:evidenceKind(r)==='agency-assessment'?'assessment':'report',reviewedAt:r.readAt}));
const evidenceLabel=evidenceKindLabel;
const stamp=value=>value?new Date(value).toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'UTC'})+' UTC':'Not retrieved';

export function evidenceLedgerState({records=[],maritime=null,failed=false,unconfigured=false,sources=[]}={}){
  const official=sources.filter(source=>source.group==='maritime'&&!source.retired&&source.configured===true);
  const unavailable=failed||official.length>0&&official.every(source=>['unavailable','retained'].includes(source.status));
  const pending=!unconfigured&&!unavailable&&(!maritime||official.some(source=>source.status==='loading')&&!official.some(source=>source.successfulCheck));
  const retained=records.some(record=>(maritime?.events||[]).some(event=>event.id===record.id));
  const incidents=records.filter(record=>record.recordType==='incident').length;
  let basis=`${incidents} incident entries · ${records.length-incidents} statements / assessments`;
  if(unconfigured)basis='Live data is not configured'+(records.length?' · dated reference context only':'');
  else if(unavailable)basis=retained?basis+' · previously retrieved evidence; current coverage is unavailable':records.length?'Dated reference context · current official coverage is unavailable':'Official records are unavailable.';
  else if(pending)basis='Checking official records…'+(records.length?' · dated reference context shown below':'');
  else if(official.some(source=>source.attention))basis+=' · some official-source updates need attention';
  const empty=unconfigured?'Connect a live-data service to check official records.':unavailable?'No official records are available in this view. Missing coverage does not establish an absence of incidents.':pending?'Waiting for official-source responses. Coverage is not yet established.':'No retrieved evidence matches this window and channel. This does not establish an absence of incidents.';
  return {basis,empty,canReview:records.length>0};
}

export function advisoryCoverageMarkup(state,sources,now=Date.now()){
  const source=sources.find(value=>value.id==='marad-advisories');
  const records=(state.maritime?.advisories||[]).filter(record=>state.theater==='both'||record.theaters?.includes(state.theater));
  const available=source?.configured!==false&&!source?.retired&&source?.successfulCheck&&!source?.attention;
  const row=record=>`<article class="incident-row advisory-row"><div class="incident-copy"><div class="incident-meta"><span>Archived advisory</span><span>Source status at retrieval: ${esc(record.sourceStatus||'unknown')}</span></div><button class="incident-title" data-evidence="${esc(record.id)}">${esc(record.title)} ↗</button><p>Validity from archived dates: ${esc(advisoryValidity(record,now))}. Effective ${esc(date(record.effectiveDate))} · expires ${esc(date(record.expiresDate))}${record.supersededBy?.length?' · superseded by '+esc(record.supersededBy.join(', ')):''}</p><p>Retrieved ${esc(record.retrievedAt||source?.retrievedAt?stamp(record.retrievedAt||source.retrievedAt):'at an unknown time')} · ${esc(record.source||'U.S. Maritime Advisories')}</p></div></article>`;
  const note=available?'Advisory metadata is available; validity dates do not establish safe passage.':'Current maritime advisories are unavailable. This is not an all-clear.';
  return `<p class="ledger-basis advisory-coverage">${note}</p>${records.length?`<details class="ledger-source-notes advisory-archive"><summary>${records.length} archived ${records.length===1?'advisory':'advisories'}</summary><p>Historical evidence with original dates and source links. Current validity has not been verified; missing notices do not establish an absence of incidents.</p>${records.map(row).join('')}</details>`:''}`;
}

export function createSituationView({getState,getSources,openDialog,openInspector=openDialog,onSources,onFocus,onInfrastructure,now=Date.now}) {
  let days='30',mechanism='all';
  const rendered=new Map();
  const allRecords=()=>[...(getState().maritime?.events||[]),...(getState().maritime?.advisories||[]),...(runtime.hosted?[]:MARKET_CONTEXT.filter(r=>!reviewedContext.some(c=>c.url===r.url))),...(runtime.hosted?[]:reviewedContext)];
  const filtered=()=>selectEvidence(allRecords().filter(record=>record.recordType!=='advisory'),{theater:getState().theater,days,mechanism});
  function replace(id,html){const element=document.getElementById(id);if(!element||rendered.get(id)===html)return;const focused=document.activeElement,focusId=element.contains(focused)?focused.id:null,open=element.querySelector('details')?.open;element.innerHTML=html;rendered.set(id,html);if(open&&element.querySelector('details'))element.querySelector('details').open=true;if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});}
  function recordRow(record){
    const mechanisms=oilMechanisms(record).filter(m=>m.id!=='people').slice(0,2);
    return `<article class="incident-row"><time class="incident-date" datetime="${esc(evidenceDate(record))}">${esc(date(evidenceDate(record)))}<small>${record.eventDate?'Event date':'Published'}</small></time><div class="incident-copy"><div class="incident-meta"><span>${evidenceLabel(record)}</span>${record.reviewedAt?'<span>Curated</span>':''}</div><button class="incident-title" data-evidence="${esc(record.id)}">${esc(record.title)} <span aria-hidden="true">↗</span></button><p>${esc(record.locationText||record.source)}</p><div class="incident-mechanism">${mechanisms.map(m=>`<span>${esc(m.name)}</span>`).join('')}</div></div></article>`;
  }
  function update(){
    const state=getState(),sources=getSources(),age=contextAge(COVERAGE_REVIEW_DATE);
    const currentContext=reviewedContext.slice(0,2).filter(r=>state.theater==='both'||r.theaters.includes(state.theater));
    replace('situation-brief',runtime.hosted?`<div class="brief-intro"><span class="brief-kicker">SOURCE CONTEXT</span><h2 class="brief-title">Follow the evidence.</h2><p class="brief-copy">Use retrieved reports and official records to examine possible oil-market mechanisms. Price observations keep their own dates.</p></div><p class="brief-disclosure">${runtime.configurationError?'Live data is not configured. Reference geography is available; it does not establish current conditions.':'Open a report to inspect its source, dates and connection to the market. Missing coverage remains explicit.'}</p>`:`<div class="brief-intro"><span class="brief-kicker">SITUATION CONTEXT <span class="brief-meta">${esc(age.label)}</span></span><h2 class="brief-title">Follow the barrels. <span>Understand the pressure.</span></h2><p class="brief-copy">Security, export routes and market buffers connect these waters to oil prices.</p></div><div class="brief-signals">${currentContext.map(r=>`<button class="brief-signal" data-evidence="${r.id}"><span>${esc(r.source)} · ${esc(date(r.publishedDate))}</span><strong>${esc(r.title)}</strong><small>${esc(r.recordType==='report'?'Reported claims · operating status requires confirmation':'Dated agency assessment · not a live measurement')} ↗</small></button>`).join('')}</div><p class="brief-disclosure">${age.needsReview?'This briefing needs a new source review. ':''}Curated context is dated above; automatic feed checks do not update these assessments.</p>`);
    const records=filtered(),ledger=evidenceLedgerState({records,maritime:state.maritime,failed:Boolean(state.failures?.maritime),unconfigured:runtime.configurationError,sources});
    replace('incident-ledger',`<div class="ledger-controls"><label>Evidence window<select id="evidence-days" aria-label="Evidence window"><option value="30" ${days==='30'?'selected':''}>30 days</option><option value="90" ${days==='90'?'selected':''}>90 days</option><option value="all" ${days==='all'?'selected':''}>All retrieved</option></select></label><label>Oil channel<select id="evidence-mechanism" aria-label="Oil channel"><option value="all">All channels</option>${MECHANISMS.map(m=>`<option value="${m.id}" ${mechanism===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label></div><p class="ledger-basis">${esc(ledger.basis)}</p><div class="incident-list">${records.slice(0,4).map(recordRow).join('')||`<p class="empty">${esc(ledger.empty)}</p>`}</div>${advisoryCoverageMarkup(state,sources,now())}<div class="ledger-footer">${ledger.canReview?`<button class="text-button" data-evidence-all>Review all ${records.length} records ↗</button>`:''}<button class="text-button" data-coverage-details>Source diagnostics</button></div><details class="ledger-source-notes"><summary>Dates & coverage</summary><p>Incident dates and statement publication dates are separate. Red Sea statements are not a complete incident ledger. Reported locations and responsibility remain as attributed by the original source.</p></details>`);
    const actors=REGIONAL_ACTORS.filter(a=>state.theater==='both'||a.theaters.includes(state.theater));
    replace('regional-context',`<p class="regional-basis">How the regional system connects to oil. Geographic references and source-linked context; operating status is separately dated.</p><div class="regional-grid">${actors.map(a=>`<button class="regional-card" data-region="${a.id}"><span class="regional-kicker">${esc(a.role)}</span><strong>${esc(a.name)} <span aria-hidden="true">↗</span></strong><p>${esc(a.summary)}</p><span class="regional-facts">${esc(a.channel)}</span></button>`).join('')}</div>`);
    const groups=(ids)=>ids.map(id=>sources.find(s=>s.id===id)).filter(Boolean);
    const stateFor=list=>list.some(s=>s.hasData)?list.some(s=>s.attention)?'Partial · attention needed':'Available · source lag':list.some(s=>s.status==='loading')?'Checking':'Unavailable';
    const prices=groups(['brent','wti']), maritime=groups(['imo-hormuz','imo-redsea']), vessels=groups(['aisstream','openwaters']);
    const blocks=[
      ['Oil prices',stateFor(prices),'EIA daily spot observations; no intraday futures. '+prices.map(s=>`${s.name}: ${s.latest||'no observation'}`).join(' · '),'sources'],
      ['Maritime incidents',stateFor(maritime),'IMO table and dated statements. Red Sea event coverage remains partial.','sources'],
      ['Tanker reception',stateFor(vessels),'AIS positions expire at 30 minutes. Tanker type does not prove oil cargo or completed passage.','sources'],
      ['Physical oil flows','Historical baseline','EIA H1 2025 exposure is available. Current barrels, cargoes and terminal loadings are not connected.','https://portwatch.imf.org/'],
      runtime.hosted?['Inventories & demand','Weekly U.S. context','U.S. commercial crude stocks and refinery utilization are separately dated in Market backdrop. They do not measure regional oil flows.','https://www.eia.gov/petroleum/supply/weekly/']:['Inventories & demand','Dated agency context','September EIA and IEA assessments; no automatically refreshed global stock balance.','https://www.iea.org/reports/oil-market-report-september-2026'],
      ['Freight & insurance','Not connected','No live tanker freight, war-risk premium or refining margin series. Do not infer these from crude prices.','/data-upgrades.html']
    ];
    replace('coverage-matrix',`<div class="coverage-grid">${blocks.map(([title,status,copy,target])=>`<article class="coverage-item"><div><strong>${title}</strong><span class="coverage-state">${status}</span></div><p>${esc(copy)}</p>${target==='sources'?'<button class="text-button" data-coverage-details>Inspect source clocks ↗</button>':link(target,target==='/data-upgrades.html'?'Free-source guide':'Open reference')}</article>`).join('')}</div><p class="coverage-footer">A complete market assessment combines these categories. Passage makes each available layer and missing measurement explicit.</p>`);
    bind(document.getElementById('situation-brief'));bind(document.getElementById('incident-ledger'));bind(document.getElementById('regional-context'));bind(document.getElementById('coverage-matrix'));
    const windowSelect=document.getElementById('evidence-days');if(windowSelect)windowSelect.onchange=e=>{days=e.target.value;update();};
    const channelSelect=document.getElementById('evidence-mechanism');if(channelSelect)channelSelect.onchange=e=>{mechanism=e.target.value;update();};
  }
  function bind(root){
    if(!root)return;
    root.querySelectorAll('[data-evidence]').forEach(b=>b.onclick=()=>showEvidence(b.dataset.evidence));
    root.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>showRegion(b.dataset.region));
    root.querySelectorAll('[data-coverage-details]').forEach(b=>b.onclick=onSources);
    root.querySelectorAll('[data-evidence-all]').forEach(b=>b.onclick=showAll);
  }
  function showAll(){openDialog('MARITIME & ENERGY EVIDENCE',`<h2>The evidence behind the watch</h2><p>Current theater · ${days==='all'?'all retrieved dates':days+' days'} · ${mechanism==='all'?'all oil channels':esc(MECHANISMS.find(m=>m.id===mechanism)?.name)}. Statements and incidents remain distinct.</p><div class="incident-list incident-list-expanded">${filtered().map(recordRow).join('')||'<p>No records match the current evidence filters.</p>'}</div>`);bind(document.getElementById('dialog-content'));}
  function showEvidence(id){
    const r=allRecords().find(r=>r.id===id);if(!r)return;
    const state=getState(),source=getSources().find(s=>s.id===r.sourceId),sourceUrl=safeEvidenceUrl(r.url),channels=oilMechanisms(r),nonEvent=['assessment','advisory','forecast'].includes(r.recordType);
    const advisoryDates=r.recordType==='advisory'?`<dl class="vessel-facts"><div><dt>Validity from archived dates</dt><dd>${esc(advisoryValidity(r,now()))}</dd></div><div><dt>Source status at retrieval</dt><dd>${esc(r.sourceStatus||'unknown')}</dd></div><div><dt>Effective date</dt><dd>${esc(date(r.effectiveDate))}</dd></div><div><dt>Expiry date</dt><dd>${esc(date(r.expiresDate))}</dd></div><div><dt>Supersedes</dt><dd>${esc(r.supersedes?.join(', ')||'None listed')}</dd></div><div><dt>Superseded by</dt><dd>${esc(r.supersededBy?.join(', ')||'None listed')}</dd></div></dl><p>Advisory validity dates are not publication or event timestamps. The notice does not establish a specific incident or current route operating status.</p>`:'';
    const comparisons=(state.oil?.series||[]).map(s=>({name:s.name,...priceComparison(s.observations||[],r.eventDate)}));
    openInspector(evidenceLabel(r).toUpperCase(),`<h2>${esc(r.title)}</h2>${evidencePanelMarkup(r,{source})}${advisoryDates}${r.summary?`<h3>Source account</h3><p>${esc(r.summary)}</p>`:''}${r.attributionNote?`<p class="muted">${esc(r.attributionNote)}</p>`:''}<h3>Potential oil-market channels</h3>${channels.length?channels.map(m=>`<div class="evidence-channel"><strong>${esc(m.name)}</strong><p>${esc(m.explanation)}</p></div>`).join(''):'<p>No direct oil channel identified from the available text.</p>'}${r.watch?`<p class="evidence-watch"><strong>What to verify next</strong><br>${esc(r.watch)}</p>`:''}${nonEvent?'<h3>Separately dated market context</h3><p>This record does not establish a single event timestamp. Daily Brent and WTI observations remain separately dated in the oil panel.</p>':'<h3>Price observations on the event date</h3>'}<div ${nonEvent?'hidden':''}><p class="muted">${r.eventDate?'Exact calendar-date match, compared with the previous available daily observation.':'A publication date is not substituted for an unknown event date.'} This comparison does not measure causation or the market’s reaction after the event time.</p><div class="price-comparison">${comparisons.map(s=>`<div><strong>${esc(s.name)}</strong><span>${s.onDate?dollars(s.onDate.value)+' · '+date(s.onDate.date):'No exact event-date observation'}</span><small>${s.delta!==null?`${s.delta>=0?'+':''}${dollars(s.delta)} (${s.percent>=0?'+':''}${s.percent?.toFixed(2)}%) vs ${date(s.before.date)}`:s.before?'Previous available: '+dollars(s.before.value)+' · '+date(s.before.date):'Comparison unavailable'}</small></div>`).join('')||'<p>EIA observations are unavailable.</p>'}</div></div>${sourceUrl?`<div class="detail-actions"><a class="text-button" href="${esc(siteUrl('/investigate.html'))}?source=${encodeURIComponent(sourceUrl)}">Explore connections ↗</a></div>`:''}`,{context:{kind:'evidence',id:r.id,theaters:r.theaters,description:`${evidenceLabel(r)} · ${(r.theaters||[]).map(t=>t==='bab'?'Bab el-Mandeb':'Hormuz').join(' / ')} · precise location not inferred`}});
  }
  function showRegion(id){
    const actor=REGIONAL_ACTORS.find(a=>a.id===id);if(!actor)return;
    openInspector('REGIONAL OIL SYSTEM',`<h2>${esc(actor.name)}</h2><div class="detail-meta">${esc(actor.role)} · ${REVIEW_DATE?'curated context reviewed '+date(REVIEW_DATE):'Geographic reference · operating status separately sourced'}</div><p>${esc(actor.summary)}</p><h3>Oil-market connection</h3><p>${esc(actor.channel)}</p><h3>What to watch</h3><p>${esc(actor.watch)}</p><p class="evidence-watch">${esc(actor.limit)}</p>${actor.points.length?`<h3>Geographic references</h3><p>${actor.points.map(p=>esc(p.name)).join(' · ')}. Approximate map references; no operational status is encoded in the marker.</p>`:''}<div class="detail-actions">${actor.theaters.map(t=>`<button class="text-button" data-region-focus="${t}">Focus ${t==='bab'?'Bab el-Mandeb':'Hormuz'}</button>`).join('')}</div><div class="detail-actions"><a class="text-button" href="${esc(siteUrl('/investigate.html'))}?actor=${encodeURIComponent(({saudi:"saudi-arabia",us:"us-military",gulf:"iraq",eu:"maritime-coalitions"})[id]||id)}">Investigate related reporting ↗</a></div><h3>Source trail</h3><ul>${actor.sources.map(id=>`<li>${link(CONTEXT_SOURCES[id].url,CONTEXT_SOURCES[id].name)}</li>`).join('')}</ul>`,{context:{kind:'region',id:actor.id,theaters:actor.theaters,description:`${actor.name} · dated regional context · operating status separately sourced`}});
    document.querySelectorAll('[data-region-focus]').forEach(b=>b.onclick=()=>{document.getElementById('detail-dialog').close();onFocus(b.dataset.regionFocus);onInfrastructure?.();document.getElementById('map-heading').scrollIntoView({block:'start',behavior:'instant'});});
  }
  function showAsset(id){
    const asset=INFRASTRUCTURE.find(point=>point.id===id);
    if(!asset){showRegion(id);return;}
    const actor=REGIONAL_ACTORS.find(region=>region.id===asset.actorId);
    const coordinates=`${Math.abs(asset.latitude).toFixed(2)}° ${asset.latitude<0?'S':'N'} · ${Math.abs(asset.longitude).toFixed(2)}° ${asset.longitude<0?'W':'E'}`;
    openInspector('ENERGY INFRASTRUCTURE',`<h2>${esc(asset.name)}</h2><div class="detail-meta">${esc(actor.name)} · approximate geographic reference</div><dl class="vessel-facts"><div><dt>Reference coordinates</dt><dd>${esc(coordinates)}</dd></div><div><dt>Position basis</dt><dd>${esc(asset.basis)}</dd></div><div><dt>Context reviewed</dt><dd>${esc(date(REVIEW_DATE))}</dd></div><div><dt>Live operating status</dt><dd>Not connected</dd></div></dl><h3>Regional oil connection</h3><p>${esc(actor.summary)}</p><p><strong>${esc(actor.channel)}</strong></p><h3>What to verify</h3><p>${esc(actor.watch)}</p><p class="evidence-watch">${esc(actor.limit)}</p><h3>Source trail</h3><ul>${actor.sources.map(source=>`<li>${link(CONTEXT_SOURCES[source].url,CONTEXT_SOURCES[source].name)}</li>`).join('')}</ul><div class="detail-actions"><button class="text-button" data-asset-region="${esc(actor.id)}">Inspect ${esc(actor.name)} context ↗</button></div>`,{context:{kind:'asset',id:asset.id,theaters:asset.theaters,description:`${asset.name} · approximate reference · live operating status unavailable`}});
    document.querySelector('[data-asset-region]')?.addEventListener('click',()=>showRegion(actor.id));
  }
  return {update,showEvidence,showRegion,showAsset,exportEvidence:()=>({events:filtered().map(withEvidenceKind),advisories:(getState().maritime?.advisories||[]).filter(record=>getState().theater==='both'||record.theaters?.includes(getState().theater)).map(withEvidenceKind),coverage:getState().maritime?.coverage||null,windowDays:days,mechanism,curatedReviewDate:REVIEW_DATE,sourceNote:'Incident dates and statement publication dates are distinct. Selected records may cover the same occurrence. No inferred incident coordinates or causal oil effect.'})};
}
